import { test, expect } from '@playwright/test';

test.describe('Search Tolerance for Minor Spelling Mistakes', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should return results for search with minor spelling mistakes', async ({ page }) => {
    // Set up API interception for search
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Perform search with minor spelling mistake
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('playwright test script');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for results to load
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await page.waitForSelector(resultsContainer);

    // Verify results are displayed
    await expect(resultsContainer).toBeVisible();
    const resultItem = page.getByText('Playwright Test Script');
    await expect(resultItem).toBeVisible();

    // Verify result item has correct link
    const resultLink = page.getByRole('link', { name: /playwright test script/i });
    await expect(resultLink).toBeVisible();

    // Verify result item has correct title
    await expect(resultItem).toContainText('Playwright Test Script');

    // Verify result item has correct description
    const resultDescription = page.getByText('A Playwright script for automated Playwright tests');
    await expect(resultDescription).toBeVisible();
  });

  test('should handle search with multiple minor spelling mistakes', async ({ page }) => {
    // Set up API interception for search
    await page.route('**/api/search', (route) => {
      route.continue();
    });

    // Perform search with multiple minor spelling mistakes
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('playwright test script');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for results to load
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await page.waitForSelector(resultsContainer);

    // Verify results are displayed
    await expect(resultsContainer).toBeVisible();

    // Verify result item with minor spelling mistake is still visible
    const resultItem = page.getByText('Playwright Test Script');
    await expect(resultItem).toBeVisible();

    // Verify result item has correct link
    const resultLink = page.getByRole('link', { name: /playwright test script/i });
    await expect(resultLink).toBeVisible();

    // Verify result item has correct title
    await expect(resultItem).toContainText('Playwright Test Script');

    // Verify result item has correct description
    const resultDescription = page.getByText('A Playwright script for automated Playwright tests');
    await expect(resultDescription).toBeVisible();

    // Verify result item with different minor spelling mistake is also visible
    const resultItem2 = page.getByText('Playwright Test Script');
    await expect(resultItem2).toBeVisible();

    // Verify result item with different minor spelling mistake has correct link
    const resultLink2 = page.getByRole('link', { name: /playwright test script/i });
    await expect(resultLink2).toBeVisible();

    // Verify result item with different minor spelling mistake has correct title
    await expect(resultItem2).toContainText('Playwright Test Script');

    // Verify result item with different minor spelling mistake has correct description
    const resultDescription2 = page.getByText('A Playwright script for automated Playwright tests');
    await expect(resultDescription2).toBeVisible();
  });
});
